+import { minorUnitFactor } from "~/lib/money";
+
+export interface InvoiceCsvRow {
+  invoiceNumber: string;
+  company: { name: string };
+  currencyCode: string;
+  issueDate: Date | string;
+  dueDate: Date | string | null;
+  totalMinor: number | bigint;
+  paidMinor: number | bigint;
+  status: string;
+}
+
+const HEADER = [
+  "invoice_number",
+  "company",
+  "currency",
+  "issue_date",
+  "due_date",
+  "total",
+  "paid",
+  "balance_due",
+  "status",
+];
+
+function csvField(value: string | number): string {
+  const text = String(value);
+  return /[",\r\n]/.test(text) ? `"${text.replaceAll('"', '""')}"` : text;
+}
+
+function calendarDate(value: Date | string | null): string {
+  return value === null ? "" : new Date(value).toISOString().slice(0, 10);
+}
+
+function integerMinor(value: number | bigint): bigint {
+  return typeof value === "bigint" ? value : BigInt(Math.trunc(value));
+}
+
+function formatAmount(minor: number | bigint, currency: string): string {
+  const amount = integerMinor(minor);
+  const factor = BigInt(minorUnitFactor(currency));
+  const absolute = amount < 0n ? -amount : amount;
+  const whole = absolute / factor;
+  const sign = amount < 0n ? "-" : "";
+  if (factor === 1n) return `${sign}${whole}`;
+  return `${sign}${whole}.${String(absolute % factor).padStart(2, "0")}`;
+}
+
+function balanceDue(invoice: InvoiceCsvRow): bigint {
+  if (["DRAFT", "VOID", "PAID"].includes(invoice.status)) return 0n;
+  const due = integerMinor(invoice.totalMinor) - integerMinor(invoice.paidMinor);
+  return due > 0n ? due : 0n;
+}
+
+export function createInvoiceCsv(invoices: InvoiceCsvRow[]): string {
+  const rows = invoices.map((invoice) => [
+    invoice.invoiceNumber,
+    invoice.company.name,
+    invoice.currencyCode,
+    calendarDate(invoice.issueDate),
+    calendarDate(invoice.dueDate),
+    formatAmount(invoice.totalMinor, invoice.currencyCode),
+    formatAmount(invoice.paidMinor, invoice.currencyCode),
+    formatAmount(balanceDue(invoice), invoice.currencyCode),
+    invoice.status,
+  ]);
+  return `\uFEFF${[HEADER, ...rows].map((row) => row.map(csvField).join(",")).join("\r\n")}\r\n`;
+}
