+export interface AgingInvoice {
+  status: string;
+  currencyCode: string;
+  totalMinor: number | bigint;
+  paidMinor: number | bigint;
+  dueDate: Date | string | null;
+}
+
+export interface AgingBuckets {
+  current: number;
+  "1-30": number;
+  "31-60": number;
+  "61-90": number;
+  "90+": number;
+}
+
+export interface AgingRow {
+  currency: string;
+  buckets: AgingBuckets;
+  totalMinor: number;
+}
+
+const DAY_MS = 86_400_000;
+const OPEN_STATUSES = new Set(["SENT", "PARTIAL", "OVERDUE"]);
+
+function isoDate(value: Date | string): string {
+  return value instanceof Date ? value.toISOString().slice(0, 10) : value.slice(0, 10);
+}
+
+function utcDay(value: string): number {
+  const [year, month, day] = value.split("-").map(Number);
+  return Date.UTC(year, month - 1, day);
+}
+
+export function agingReport(invoices: AgingInvoice[], asOf: string): AgingRow[] {
+  const rows = new Map<string, AgingRow>();
+  const asOfDay = utcDay(asOf);
+
+  for (const invoice of invoices) {
+    if (!OPEN_STATUSES.has(invoice.status)) continue;
+    const total = Number(invoice.totalMinor);
+    const paid = Number(invoice.paidMinor);
+    const balance = Math.max(0, total - paid);
+    if (balance <= 0) continue;
+
+    let row = rows.get(invoice.currencyCode);
+    if (!row) {
+      row = {
+        currency: invoice.currencyCode,
+        buckets: { current: 0, "1-30": 0, "31-60": 0, "61-90": 0, "90+": 0 },
+        totalMinor: 0,
+      };
+      rows.set(invoice.currencyCode, row);
+    }
+
+    const daysPastDue = invoice.dueDate === null
+      ? 0
+      : Math.floor((asOfDay - utcDay(isoDate(invoice.dueDate))) / DAY_MS);
+    const bucket = daysPastDue <= 0
+      ? "current"
+      : daysPastDue <= 30
+        ? "1-30"
+        : daysPastDue <= 60
+          ? "31-60"
+          : daysPastDue <= 90
+            ? "61-90"
+            : "90+";
+    row.buckets[bucket] += balance;
+    row.totalMinor += balance;
+  }
+
+  return [...rows.values()].sort((a, b) => a.currency.localeCompare(b.currency));
+}
